import type { MessageParameters } from "../../src/shared/i18n/index.js";

/** Runtime samples establish output validity; TypeScript checks the payload contract separately. */
export function validateCatalog(candidate: unknown): string[] {
  if (candidate === undefined || candidate === null) return ["missing-catalog"];
  if (typeof candidate !== "object") return ["invalid-catalog"];
  const catalog = candidate as Record<string, unknown>;
  const errors: string[] = [];
  if (Object.keys(catalog).length === 0) errors.push("empty-catalog");
  for (const key of Object.keys(catalog)) {
    if (!Object.hasOwn(catalogSamples, key)) errors.push(`unexpected:${key}`);
  }
  for (const [key, sample] of Object.entries(catalogSamples)) {
    if (!Object.hasOwn(catalog, key)) {
      errors.push(`missing:${key}`);
      continue;
    }
    const phrase = catalog[key];
    if (typeof phrase !== "function") {
      errors.push(`noncallable:${key}`);
      continue;
    }
    try {
      const output: unknown = phrase(sample);
      if (
        typeof output !== "string" ||
        output.includes("undefined") ||
        output.includes("[object Object]")
      )
        errors.push(`invalid-output:${key}`);
      else if (output.trim().length === 0) errors.push(`empty-output:${key}`);
      else if (
        !output.isWellFormed() ||
        Buffer.from(output).toString("utf8") !== output
      )
        errors.push(`invalid-encoding:${key}`);
    } catch {
      errors.push(`payload-error:${key}`);
    }
  }
  return errors;
}

